description:
Write a generic stack and two generic functions:

```rust
#[derive(Debug, Default)]
struct Stack<T> { items: Vec<T> }

impl<T> Stack<T> {
    fn new() -> Self
    fn push(&mut self, item: T)
    fn pop(&mut self) -> Option<T>
    fn peek(&self) -> Option<&T>
    fn len(&self) -> usize
    fn is_empty(&self) -> bool
}

impl<T: std::fmt::Display> Stack<T> {
    fn render(&self) -> String            // bottom to top, "[1 | 2 | 3]"; "[]" when empty
}

fn min_max<T: PartialOrd + Copy>(items: &[T]) -> Option<(T, T)>
fn dedup_sorted<T: PartialEq + Clone>(items: &[T]) -> Vec<T>        // drops consecutive repeats
```

solution.solution.rs:
use std::fmt::Display;

#[derive(Debug, Default)]
struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    fn new() -> Self {
        Stack { items: Vec::new() }
    }

    fn push(&mut self, item: T) {
        self.items.push(item);
    }

    fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    fn peek(&self) -> Option<&T> {
        self.items.last()
    }

    fn len(&self) -> usize {
        self.items.len()
    }

    fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

impl<T: Display> Stack<T> {
    fn render(&self) -> String {
        let parts: Vec<String> = self.items.iter().map(|i| i.to_string()).collect();
        format!("[{}]", parts.join(" | "))
    }
}

fn min_max<T: PartialOrd + Copy>(items: &[T]) -> Option<(T, T)> {
    let first = *items.first()?;
    let mut lo = first;
    let mut hi = first;
    for &x in items {
        if x < lo { lo = x; }
        if x > hi { hi = x; }
    }
    Some((lo, hi))
}

fn dedup_sorted<T: PartialEq + Clone>(items: &[T]) -> Vec<T> {
    let mut out: Vec<T> = Vec::new();
    for item in items {
        if out.last() != Some(item) {
            out.push(item.clone());
        }
    }
    out
}

unitTests:
test("a stack of numbers", || {
    let mut s = Stack::new();
    check(s.is_empty());
    s.push(1);
    s.push(2);
    s.push(3);
    check_eq(s.len(), 3);
    check_eq(s.peek(), Some(&3));
    check_eq(s.render(), "[1 | 2 | 3]");
    check_eq(s.pop(), Some(3));
    check_eq(s.pop(), Some(2));
    check_eq(s.render(), "[1]");
});

test("a stack of strings and of anything", || {
    let mut s: Stack<String> = Stack::default();
    check_eq(s.render(), "[]");
    s.push("tea".to_string());
    check_eq(s.pop().as_deref(), Some("tea"));
    check_eq(s.pop(), None);
    let mut v: Stack<Vec<u8>> = Stack::new();
    v.push(vec![1, 2]);
    check_eq(v.peek().map(|x| x.len()), Some(2));
});

test("min and max", || {
    check_eq(min_max(&[4, 9, 1, 7]), Some((1, 9)));
    check_eq(min_max(&[2.5, -1.0]), Some((-1.0, 2.5)));
    check_eq(min_max(&['q', 'a', 'z']), Some(('a', 'z')));
    check_eq(min_max::<i32>(&[]), None);
});

test("deduplicating", || {
    check_eq(dedup_sorted(&[1, 1, 2, 3, 3, 3, 1]), vec![1, 2, 3, 1]);
    check_eq(dedup_sorted(&["a", "a", "b"]), vec!["a", "b"]);
    check_eq(dedup_sorted::<u8>(&[]), Vec::<u8>::new());
});

